import React, { useState, useEffect } from 'react';
import { Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import toast from 'react-hot-toast';

// Components
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Pipelines from './pages/Pipelines';
import Alerts from './pages/Alerts';
import Metrics from './pages/Metrics';
import PipelineDetail from './pages/PipelineDetail';
import Header from './components/Header';

// Context
import { SocketContext } from './context/SocketContext';
import { AlertContext } from './context/AlertContext';

function App() {
  const [socket, setSocket] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [alerts, setAlerts] = useState([]);
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    // Initialize Socket.IO connection
    const newSocket = io('http://localhost:5000', {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      reconnectionAttempts: 5,
    });

    newSocket.on('connect', () => {
      console.log('Connected to server');
      setIsConnected(true);
      toast.success('Connected to dashboard server');

      // Join dashboard room
      newSocket.emit('join-dashboard');
    });

    newSocket.on('disconnect', () => {
      console.log('Disconnected from server');
      setIsConnected(false);
      toast.error('Disconnected from dashboard server');
    });

    newSocket.on('connect_error', (error) => {
      console.error('Connection error:', error);
      toast.error('Failed to connect to dashboard server');
    });

    // Listen for new alerts
    newSocket.on('new-alert', (alertData) => {
      console.log('New alert received:', alertData);
      setAlerts(prev => [alertData, ...prev.slice(0, 9)]); // Keep last 10 alerts

      // Show toast notification
      toast.custom((t) => (
        <div className={`${t.visible ? 'animate-enter' : 'animate-leave'} max-w-md w-full bg-white shadow-lg rounded-lg pointer-events-auto flex ring-1 ring-black ring-opacity-5`}>
          <div className="flex-1 w-0 p-4">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <div className="w-8 h-8 bg-red-100 rounded-full flex items-center justify-center">
                  <span className="text-red-600 text-sm">🚨</span>
                </div>
              </div>
              <div className="ml-3 flex-1">
                <p className="text-sm font-medium text-gray-900">
                  Pipeline Alert
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  {alertData.message || alertData.type}
                </p>
              </div>
            </div>
          </div>
          <div className="flex border-l border-gray-200">
            <button
              onClick={() => toast.dismiss(t.id)}
              className="w-full border border-transparent rounded-none rounded-r-lg p-4 flex items-center justify-center text-sm font-medium text-indigo-600 hover:text-indigo-500 focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              Close
            </button>
          </div>
        </div>
      ), {
        duration: 6000,
      });
    });

    // Listen for pipeline status changes
    newSocket.on('pipeline-status-changed', (data) => {
      console.log('Pipeline status changed:', data);
      toast.success(`Pipeline ${data.name} status: ${data.status}`);
    });

    // Listen for metrics updates
    newSocket.on('metrics-changed', (data) => {
      console.log('Metrics updated:', data);
    });

    setSocket(newSocket);

    // Cleanup on unmount
    return () => {
      newSocket.close();
    };
  }, []);

  return (
    <SocketContext.Provider value={{ socket, isConnected }}>
      <AlertContext.Provider value={{ alerts, setAlerts }}>
        <div className="h-screen flex overflow-hidden bg-gray-50">
          {/* Sidebar */}
          <Sidebar 
            open={sidebarOpen} 
            setOpen={setSidebarOpen} 
            isConnected={isConnected}
          />

          {/* Main content */}
          <div className="flex-1 overflow-hidden">
            <Header 
              sidebarOpen={sidebarOpen} 
              setSidebarOpen={setSidebarOpen}
              isConnected={isConnected}
            />

            <main className="flex-1 relative overflow-y-auto focus:outline-none">
              <div className="py-6">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 md:px-8">
                  <Routes>
                    <Route path="/" element={<Dashboard />} />
                    <Route path="/pipelines" element={<Pipelines />} />
                    <Route path="/pipelines/:id" element={<PipelineDetail />} />
                    <Route path="/alerts" element={<Alerts />} />
                    <Route path="/metrics" element={<Metrics />} />
                  </Routes>
                </div>
              </div>
            </main>
          </div>
        </div>
      </AlertContext.Provider>
    </SocketContext.Provider>
  );
}

export default App;
